35	////////////////////////////////////////////////////////////////////////////////
36	//
37	`default_nettype	none
38	// }}}
39	module	zipcore #(
40			// {{{
41			parameter	ADDRESS_WIDTH=30,	// 32-b word addr width
42			parameter [31:0] RESET_ADDRESS=32'h010_0000,
43			parameter	OPT_MPY = 0,
44			parameter [0:0]	OPT_SHIFTS = 1,
45			parameter [0:0]	OPT_DIV = 1,
46			parameter [0:0]	IMPLEMENT_FPU = 0,
47			parameter [0:0]	OPT_EARLY_BRANCHING = 1,
48			parameter [0:0]	OPT_CIS = 1'b1,
49			parameter [0:0]	OPT_SIM = 1'b0,
50			parameter [0:0]	OPT_DISTRIBUTED_REGS = 1'b1,
51			parameter	[0:0]	OPT_PIPELINED = 1'b1,
52			parameter	[0:0]	OPT_PIPELINED_BUS_ACCESS = (OPT_PIPELINED),
53			parameter	[0:0]	OPT_LOCK=1,
54			parameter	[0:0]	OPT_DCACHE = 1,
55			parameter	[0:0]	OPT_USERMODE = 1'b1,
56			parameter	[0:0]	OPT_LOWPOWER = 1'b0,
57			parameter	[0:0]	OPT_CLKGATE = 1'b1,
58			parameter	[0:0]	OPT_START_HALTED = 1'b1,
59			parameter	[0:0]	OPT_DBGPORT = 1'b1,
60			parameter	[0:0]	OPT_TRACE_PORT = 1'b0,
61			parameter	[0:0]	OPT_PROFILER = 1'b0,
62	
63			localparam	AW=ADDRESS_WIDTH
64	`ifdef	FORMAL
65			, parameter	F_LGDEPTH=4
66	`endif
67			// }}}
68		) (
69			// {{{
70			input	wire		i_clk, i_reset, i_interrupt,
71			output	wire		o_clken,
72			// Debug interface
73			// {{{
74			input	wire		i_halt, i_clear_cache,
75			input	wire	[4:0]	i_dbg_wreg,
76			input	wire		i_dbg_we,
77			input	wire	[31:0]	i_dbg_data,
78			input	wire	[4:0]	i_dbg_rreg,
79			//
80			output	wire		o_dbg_stall,
81			output	wire	[31:0]	o_dbg_reg,
82			output	reg	[2:0]	o_dbg_cc,
83			output	wire		o_break,
84			// }}}
85			// Instruction fetch interface
86			// {{{
87			output	wire		o_pf_new_pc,
88			output	wire		o_clear_icache,
89			output	wire		o_pf_ready,
90			output	wire [(AW+1):0]	o_pf_request_address,
91			input	wire		i_pf_valid, i_pf_illegal,
92			input	wire [31:0]	i_pf_instruction,
93			input	wire [(AW+1):0]	i_pf_instruction_pc,
94			// }}}
95			// Memory unit interface
96			// {{{
97			output	wire		o_clear_dcache,
98			output	wire		o_mem_ce,
99			output	wire		o_bus_lock,
100			output	wire [2:0]	o_mem_op,
101			output	wire [31:0]	o_mem_addr,
102			output	wire [31:0]	o_mem_data,
103			output	wire [AW+1:0]	o_mem_lock_pc,
104			output	wire [4:0]	o_mem_reg,
105			input	wire 		i_mem_busy, i_mem_rdbusy,
106						i_mem_pipe_stalled, i_mem_valid,
107			input	wire		i_bus_err,
108			input	wire [4:0]	i_mem_wreg,
109			input	wire [31:0]	i_mem_result,
110			// }}}
111			// Accounting outputs ... to help us count stalls and usage
112			// {{{
113			output	wire		o_op_stall,
114			output	wire		o_pf_stall,
115			output	wire		o_i_count,
116			// }}}
117			// Debug data for on-line/live tracing
118			// {{{
119			output	wire	[31:0]	o_debug,
120			//}}}
121			// (Optional) Profiler data
122			// {{{
123			output	wire		o_prof_stb,
124			output	wire [AW+1:0]	o_prof_addr,
125			output	wire [31:0]	o_prof_ticks
126			// }}}
127			// }}}
128		);
129	
130		// Local parameter definitions
131		// {{{
132		// Verilator lint_off UNUSED
133		localparam	[0:0]	OPT_MEMPIPE = OPT_PIPELINED_BUS_ACCESS;
134		localparam [(AW-1):0]	RESET_BUS_ADDRESS = RESET_ADDRESS[AW+1:2];
135		localparam	[3:0]	CPU_CC_REG = 4'he,
136					CPU_PC_REG = 4'hf;
137		localparam	[3:0]	CPU_SUB_OP = 4'h0,// also a compare instruction
138					CPU_AND_OP = 4'h1,// also a test instruction
139					CPU_BREV_OP= 4'h8,
140					CPU_MOV_OP = 4'hd;
141		localparam	CPU_CLRDCACHE_BIT=15, // Set to clr D-cache,auto clears
142				CPU_CLRICACHE_BIT=14, // Set to clr I-cache,auto clears
143				CPU_PHASE_BIT   = 13, // Set on last half of a CIS
144				CPU_FPUERR_BIT  = 12, // Set on floating point error
145				CPU_DIVERR_BIT  = 11, // Set on divide error
146				CPU_BUSERR_BIT  = 10, // Set on bus error
147				CPU_TRAP_BIT    =  9, // User TRAP has taken place
148				CPU_ILL_BIT     =  8, // Illegal instruction
149				CPU_BREAK_BIT   =  7,
150				CPU_STEP_BIT    =  6, // Will step one (or two CIS) ins
151				CPU_GIE_BIT     =  5,
152				CPU_SLEEP_BIT   =  4;
153		// Verilator lint_on  UNUSED
154		// }}}
155	
156		// Register declarations
157		// {{{
158		//	The distributed RAM style comment is necessary on the
159		// SPARTAN6 with XST to prevent XST from oversimplifying the register
160		// set and in the process ruining everything else.  It basically
161		// optimizes logic away, to where it no longer works.  The logic
162		// as described herein will work, this just makes sure XST implements
163		// that logic.
164		//
165		// (* ram_style = "distributed" *)
166		reg	[31:0]	regset	[0:(OPT_USERMODE)? 31:15];
167	
168		// Condition codes
169		// (BUS, TRAP,ILL,BREAKEN,STEP,GIE,SLEEP ), V, N, C, Z
170		reg	[3:0]	flags, iflags;
171		wire	[15:0]	w_uflags, w_iflags;
172		reg		break_en, user_step, sleep, r_halted;
173		wire		break_pending, trap, gie, ubreak, pending_interrupt,
174				stepped;
175		wire		step;
176		wire		ill_err_u;
177		reg		ill_err_i;
178		reg		ibus_err_flag;
179		wire		ubus_err_flag;
180		wire		idiv_err_flag, udiv_err_flag;
181		// Verilator coverage_off
182		wire		ifpu_err_flag, ufpu_err_flag;
183		// Verilator coverage_on
184		wire		ihalt_phase, uhalt_phase;
185	
186		// The master chip enable
187		wire		master_ce, master_stall;
188		//
189	
190		//
191		//	PIPELINE STAGE #1 :: Prefetch
192		//		Variable declarations
193		//
194		// {{{
195		reg	[(AW+1):0]	pf_pc;
196		reg			new_pc;
197		wire			clear_pipeline;
198	
199		reg			dcd_stalled;
200		// wire			pf_cyc, pf_stb, pf_we, pf_stall, pf_ack, pf_err;
201		// wire	[(AW-1):0]	pf_addr;
202		// wire			pf_valid, pf_gie, pf_illegal;
203		wire			pf_gie;
204	`ifdef	FORMAL
205		wire	[31:0]		f_dcd_insn_word;
206		wire			f_dcd_insn_gie;
207		wire			f_dcd_insn_is_pipeable;
208		reg	[31:0]		f_op_insn_word;
209		reg	[31:0]		f_alu_insn_word;
210	`endif
211	
212		assign	clear_pipeline = new_pc;
213		// }}}
214	
215		//
216		//	PIPELINE STAGE #2 :: Instruction Decode
217		//		Variable declarations
218		//
219		//
220		// {{{
221		wire	[3:0]	dcd_opn;
222		wire		dcd_ce, dcd_phase;
223		wire	[4:0]	dcd_A, dcd_B, dcd_R, dcd_preA, dcd_preB;
224		wire		dcd_Acc, dcd_Bcc, dcd_Apc, dcd_Bpc, dcd_Rcc, dcd_Rpc;
225		wire	[3:0]	dcd_F;
226		wire		dcd_wR, dcd_rA, dcd_rB,
227					dcd_ALU, dcd_M, dcd_DIV, dcd_FP,
228					dcd_wF, dcd_gie, dcd_break, dcd_lock,
229					dcd_pipe, dcd_ljmp;
230		wire		dcd_valid;
231		wire [AW+1:0]	dcd_pc /* verilator public_flat */;
232		wire	[31:0]	dcd_I;
233		wire		dcd_zI;	// true if dcd_I == 0
234		wire		dcd_A_stall, dcd_B_stall, dcd_F_stall;
235	
236		wire		dcd_illegal;
237		wire		dcd_early_branch, dcd_early_branch_stb;
238		wire [(AW+1):0]	dcd_branch_pc;
239	
240		wire		dcd_sim;
241		wire	[22:0]	dcd_sim_immv;
242		wire		prelock_stall, last_lock_insn;
243		wire		cc_invalid_for_dcd;
244		wire		pending_sreg_write;
245		// }}}
246	
247	
248		//
249		//
250		//	PIPELINE STAGE #3 :: Read Operands
251		//		Variable declarations
252		//
253		//
254		//
255		// {{{
256		// Now, let's read our operands
257		reg		op_valid /* verilator public_flat */,
258				op_valid_mem, op_valid_alu;
259		reg		op_valid_div, op_valid_fpu;
260		wire		op_stall;
261		wire	[3:0]	op_opn;
262		wire	[4:0]	op_R;
263		reg		op_Rcc;
264		wire	[4:0]	op_Aid, op_Bid;
265		wire		op_rA, op_rB;
266		reg	[31:0]	r_op_Av, r_op_Bv;
267		wire	[AW+1:0]	op_pc;
268		wire	[31:0]	w_op_Av, w_op_Bv, op_Av, op_Bv;
269		reg	[31:0]	w_pcB_v, w_pcA_v;
270		reg	[31:0]	w_op_BnI;
271		wire		op_wR;
272		reg		op_wF;
273		wire		op_gie;
274		wire	[3:0]	op_Fl;
275		reg	[6:0]	r_op_F;
276		wire	[7:0]	op_F;
277		wire		op_ce, op_phase, op_pipe;
278		reg		r_op_break;
279		wire		w_op_valid;
280		wire		op_lowpower_clear;
281		wire	[8:0]	w_cpu_info;
282		// Some pipeline control wires
283		reg	op_illegal;
284		wire	op_break;
285		wire	op_lock;
286	
287		wire		op_sim		/* verilator public_flat */;
288		wire	[22:0]	op_sim_immv	/* verilator public_flat */;
289		wire		alu_sim		/* verilator public_flat */;
290		wire	[22:0]	alu_sim_immv	/* verilator public_flat */;
291		// }}}
292	
293	
294		//
295		//
296		//	PIPELINE STAGE #4 :: ALU / Memory
297		//		Variable declarations
298		//
299		//
300		// {{{
301		wire	[(AW+1):0]	alu_pc;
302		reg	[4:0]	alu_reg;
303		reg		r_alu_pc_valid, mem_pc_valid;
304		wire		alu_pc_valid;
305		wire		alu_phase;
306		wire		alu_ce /* verilator public_flat */, alu_stall;
307		wire	[31:0]	alu_result;
308		wire	[3:0]	alu_flags;
309		wire		alu_valid, alu_busy;
310		wire		set_cond;
311		reg		alu_wR, alu_wF;
312		wire		alu_gie, alu_illegal;
313	
314	
315		wire			mem_ce, mem_stalled;
316	
317		wire		div_ce, div_error, div_busy, div_valid;
318		wire	[31:0]	div_result;
319		wire	[3:0]	div_flags;
320	
321		// Verilator coverage_off
322		wire		fpu_ce, fpu_error, fpu_busy, fpu_valid;
323		wire	[31:0]	fpu_result;
324		wire	[3:0]	fpu_flags;
325		// Verilator coverage_on
326		reg		adf_ce_unconditional;
327	
328	
329		reg		dbgv, dbg_clear_pipe;
330		reg	[31:0]	dbg_val;
331		reg	[31:0]	debug_pc;
332		reg		r_dbg_stall;
333	
334		assign	div_ce = (op_valid_div)&&(adf_ce_unconditional)&&(set_cond);
335		assign	fpu_ce = (IMPLEMENT_FPU)&&(op_valid_fpu)&&(adf_ce_unconditional)&&(set_cond);
336	
337		// }}}
338	
339		//
340		//
341		//	PIPELINE STAGE #5 :: Write-back
342		//		Variable declarations
343		//
344		// {{{
345		wire		wr_write_pc, wr_write_cc,
346				wr_write_scc, wr_write_ucc;
347		reg		wr_reg_ce, wr_flags_ce;
348		reg	[3:0]	wr_flags;
349		reg	[2:0]	wr_index;
350		wire	[4:0]	wr_reg_id;
351		reg	[31:0]	wr_gpreg_vl, wr_spreg_vl;
352		wire		w_switch_to_interrupt, w_release_from_interrupt;
353		reg	[(AW+1):0]	ipc;
354		wire	[(AW+1):0]	upc;
355		reg		last_write_to_cc;
356		wire		cc_write_hold;
357		reg		r_clear_icache;
358	
359		reg		pfpcset;
360		reg	[2:0]	pfpcsrc;
361	
362		wire		w_clken;
363		// }}}
364	
365		// }}}
366		////////////////////////////////////////////////////////////////////////
367		//
368		// MASTER: clock enable.
369		// {{{
370		////////////////////////////////////////////////////////////////////////
371		//
372		//
373		assign	master_ce = (!i_halt || alu_phase)
374					&&(!cc_write_hold)&&(!o_break)&&(!sleep);
375		// }}}
376		////////////////////////////////////////////////////////////////////////
377		//
378		// Calculate stall conditions
379		// {{{
380		////////////////////////////////////////////////////////////////////////
381		//
382		//
383		// PIPELINE STAGE #1 :: Prefetch
384		//	These are calculated externally, within the prefetch module.
385		//
386		// PIPELINE STAGE #2 :: Instruction Decode
387		// {{{
388		always @(*)
389		if (OPT_PIPELINED)
390			dcd_stalled = (dcd_valid && op_stall);
391		else
392			dcd_stalled = (!master_ce)
393				// Can't step forward when we need to be halted
394				||(ill_err_i)||(ibus_err_flag)||(idiv_err_flag)
395				||((dcd_valid || op_valid) && !dcd_early_branch)
396				||(alu_busy)||(div_busy)||(fpu_busy)||(i_mem_busy);
397		// }}}
398		//
399		// PIPELINE STAGE #3 :: Read Operands
400		// {{{
401		generate if (OPT_PIPELINED)
402		begin : GEN_OP_STALL
403			reg	r_cc_invalid_for_dcd;
404			reg	r_pending_sreg_write;
405	
406			// cc_invalid_for_dcd
407			// {{{
408			initial	r_cc_invalid_for_dcd = 1'b0;
409			always @(posedge i_clk)
410			if (clear_pipeline)
411				r_cc_invalid_for_dcd <= 1'b0;
412			else if ((alu_ce || mem_ce)&&(set_cond)&&(op_valid) &&((op_wF)
413					||((op_wR)&&(op_R[4:0] == { op_gie, CPU_CC_REG }))))
414				// If an instruction in the pipeline will write to the
415				// CC register, then we can't be allowed to release
416				// any instruction depending upon the CC register
417				// (for other than conditional execution) into the
418				// pipeline.
419				r_cc_invalid_for_dcd <= 1'b1;
420			else if (r_cc_invalid_for_dcd)
421				// While the pipeline is busy, keep r_cc_invalid_for_dcd
422				// high.
423				r_cc_invalid_for_dcd <= ((alu_busy)||(i_mem_rdbusy)||(div_busy)||(fpu_busy));
424			else
425				r_cc_invalid_for_dcd <= 1'b0;
426	
427			assign	cc_invalid_for_dcd = r_cc_invalid_for_dcd;
428			// }}}
429	
430			// pending_sreg_write
431			// {{{
432			// Used to determine if we need to stall for flags to be ready
433			initial	r_pending_sreg_write = 1'b0;
434			always @(posedge i_clk)
435			if (clear_pipeline)
436				r_pending_sreg_write <= 1'b0;
437			else if (((adf_ce_unconditional)||(mem_ce))
438					&&(set_cond)&&(!op_illegal)
439					&&(op_wR)
440					&&(op_R[3:1] == 3'h7)
441					&&(op_R[4:0] != { gie, 4'hf }))
442				r_pending_sreg_write <= 1'b1;
443			else if ((!i_mem_rdbusy)&&(!alu_busy))
444				r_pending_sreg_write <= 1'b0;
445	
446			assign	pending_sreg_write = r_pending_sreg_write;
447			// }}}
448	
449			assign	op_stall = (op_valid)&&(
450			// {{{
451				// Only stall if we're loaded w/valid insns and the
452				// next stage is accepting our instruction
453				(!adf_ce_unconditional)&&(!mem_ce)
454				)
455				||(dcd_valid)&&(
456					// If we are halted, then accepting anything
457					// into the Op stage might accept a register
458					// that then gets modified by the debugging
459					// interface so as to be invalid.
460					i_halt
461					// Stall if we need to wait for an operand A
462					// to be ready to read
463					|| (dcd_A_stall)
464					// Likewise for B, also includes logic
465					// regarding immediate offset (register must
466					// be in register file if we need to add to
467					// an immediate)
468					||(dcd_B_stall)
469					// Or if we need to wait on flags to work on the
470					// CC register
471					||(dcd_F_stall)
472				);
473			// }}}
474			assign	op_ce = ((dcd_valid)||(dcd_illegal)||(dcd_early_branch))&&(!op_stall);
475	
476		end else begin : NO_OP_STALLS // !OPT_PIPELINED
477			// {{{
478			assign	op_stall = 1'b0; // (o_break)||(pending_interrupt);
479			assign	op_ce = ((dcd_valid)||(dcd_early_branch))&&(!op_stall);
480			assign	pending_sreg_write = 1'b0;
481			assign	cc_invalid_for_dcd = 1'b0;
482	
483			// verilator coverage_off
484			// Verilator lint_off UNUSED
485			wire		pipe_unused;
486			assign		pipe_unused = &{ 1'b0, cc_invalid_for_dcd,
487						pending_sreg_write };
488			// Verilator lint_on UNUSED
489			// verilator coverage_on
490			// }}}
491		end endgenerate
492	
493		// BUT ... op_ce is too complex for many of the data operations.  So
494		// let's make their circuit enable code simpler.  In particular, if
495		// op_ doesn't need to be preserved, we can change it all we want
496		// ... right?  The clear_pipeline code, for example, really only needs
497		// to determine whether op_valid is true.
498		// assign	op_change_data_ce = (!op_stall);
499		// }}}
500		//
501		// PIPELINE STAGE #4 :: ALU / Memory
502		// {{{
503		// 1. Basic stall is if the previous stage is valid and the next is
504		//	busy.
505		// 2. Also stall if the prior stage is valid and the master clock enable
506		//	is de-selected
507		// 3. Stall if someone on the other end is writing the CC register,
508		//	since we don't know if it'll put us to sleep or not.
509		// 4. Last case: Stall if we would otherwise move a break instruction
510		//	through the ALU.  Break instructions are not allowed through
511		//	the ALU.
512		generate if (OPT_PIPELINED)
513		begin : GEN_ALU_STALL
514			// alu_stall, alu_ce
515			// {{{
516			assign	alu_stall = (((master_stall)||(i_mem_rdbusy))&&(op_valid_alu)) //Case 1&2
517				||(wr_reg_ce)&&(wr_write_cc);
518			// assign // alu_ce = (master_ce)&&(op_valid_alu)&&(!alu_stall)
519			//	&&(!clear_pipeline)&&(!op_illegal)
520			//	&&(!pending_sreg_write)
521			//	&&(!alu_sreg_stall);
522			assign	alu_ce = (adf_ce_unconditional)&&(op_valid_alu);
523	
524			// verilator coverage_off
525			// Verilator lint_off unused
526			wire	unused_alu_stall = &{ 1'b0, alu_stall };
527			// Verilator lint_on  unused
528			// verilator coverage_on
529			// }}}
530		end else begin : NO_ALU_STALLS
