708		//
709	
710		// op_pipe
711		// {{{
712		generate if (OPT_PIPELINED_BUS_ACCESS)
713		begin : GEN_OP_PIPE // Memory pipelining
714			reg		r_op_pipe;
715	
716			// To be a pipeable operation, there must be
717			//	two valid adjacent instructions
718			//	Both must be memory instructions
719			//	Both must be writes, or both must be reads
720			//	Both operations must be to the same identical address,
721			//		or at least a single (one) increment above that
722			//		address
723			//
724			// However ... we need to know this before this clock, hence
725			// this is calculated in the instruction decoder.
726			initial	r_op_pipe = 1'b0;
727			always @(posedge i_clk)
728			if ((OPT_LOWPOWER && i_reset)||(clear_pipeline)||(i_halt))
729				r_op_pipe <= 1'b0;
730			else if (op_ce)
731				r_op_pipe <= (dcd_pipe)&&(op_valid_mem)&&(!OPT_LOWPOWER || !dcd_illegal);
732			else if ((wr_reg_ce)&&(wr_reg_id == op_Bid[4:0]))
733				r_op_pipe <= 1'b0;
734			else if (mem_ce) // Clear us any time an op_ is clocked in
735				r_op_pipe <= 1'b0;
736	
737			assign	op_pipe = r_op_pipe;
738	`ifdef	FORMAL
739			always @(*)
740			if (OPT_LOWPOWER && !op_valid_mem)
741				assert(!r_op_pipe);
742	`endif
743		end else begin : NO_OP_PIPE
744	
745			assign	op_pipe = 1'b0;
746	
747		end endgenerate
748		// }}}
749	
750		// Read from our register set
751		// {{{
752		generate if (OPT_DISTRIBUTED_REGS)
753		begin : GEN_DISTRIBUTED_REGS
754			// {{{
755			if (OPT_USERMODE)
756			begin : GEN_FULL_REGSET
757	
758				assign	w_op_Av = (!OPT_LOWPOWER || dcd_valid || !OPT_PIPELINED) ? regset[dcd_A] : 32'h0;
759				assign	w_op_Bv = (!OPT_LOWPOWER || dcd_valid || !OPT_PIPELINED) ? regset[dcd_B] : 32'h0;
760	
761			end else begin : GEN_NO_USERREGS
762				assign	w_op_Av = (!OPT_LOWPOWER || dcd_valid || !OPT_PIPELINED) ? regset[dcd_A[3:0]] : 32'h0;
763				assign	w_op_Bv = (!OPT_LOWPOWER || dcd_valid || !OPT_PIPELINED) ? regset[dcd_B[3:0]] : 32'h0;
764			end
765	
766			// verilator coverage_off
767			// verilator lint_off UNUSED
768			wire	unused_prereg_addrs;
769			assign	unused_prereg_addrs = &{ 1'b0, dcd_preA, dcd_preB };
770			// verilator lint_on  UNUSED
771			// verilator coverage_on
772			// }}}
773		end else begin : GEN_BLOCKRAM
774			// {{{
775			reg	[31:0]	pre_rewrite_value, pre_op_Av, pre_op_Bv;
776			reg		pre_rewrite_flag_A, pre_rewrite_flag_B;
777	
778			always @(posedge i_clk)
779			if (dcd_ce)
780			begin
781				pre_rewrite_flag_A <= (wr_reg_ce)&&(dcd_preA == wr_reg_id);
782				pre_rewrite_flag_B <= (wr_reg_ce)&&(dcd_preB == wr_reg_id);
783				pre_rewrite_value  <= wr_gpreg_vl;
784			end else if (OPT_PIPELINED && dcd_valid)
785			begin
786				pre_rewrite_flag_A <= (wr_reg_ce)&&(dcd_A == wr_reg_id);
787				pre_rewrite_flag_B <= (wr_reg_ce)&&(dcd_B == wr_reg_id);
788				pre_rewrite_value  <= wr_gpreg_vl;
789			end
790	
791			if (OPT_USERMODE)
792			begin : GEN_FULL_REGSET
793	
794				always @(posedge i_clk)
795				if (dcd_ce || (OPT_PIPELINED && dcd_valid))
796					pre_op_Av <= regset[dcd_ce ? dcd_preA : dcd_A];
797	
798				always @(posedge i_clk)
799				if (dcd_ce || (OPT_PIPELINED && dcd_valid))
800					pre_op_Bv <= regset[dcd_ce ? dcd_preB : dcd_B];
801	
802			end else begin : GEN_NO_USERREGS
803				always @(posedge i_clk)
804				if (dcd_ce || (OPT_PIPELINED && dcd_valid))
805					pre_op_Av <= regset[dcd_ce ? dcd_preA[3:0] : dcd_A[3:0]];
806	
807				always @(posedge i_clk)
808				if (dcd_ce || (OPT_PIPELINED && dcd_valid))
809					pre_op_Bv <= regset[dcd_ce ? dcd_preB[3:0] : dcd_B[3:0]];
810			end
811	
812			assign	w_op_Av = (pre_rewrite_flag_A) ? pre_rewrite_value : pre_op_Av;
813			assign	w_op_Bv = (pre_rewrite_flag_B) ? pre_rewrite_value : pre_op_Bv;
814			// }}}
815		end endgenerate
816		// }}}
817	
818		assign	w_cpu_info = {
819		// {{{
820		1'b1,
821		(OPT_MPY    >0)? 1'b1:1'b0,
822		(OPT_DIV >0)? 1'b1:1'b0,
823		(IMPLEMENT_FPU    >0)? 1'b1:1'b0,
824		OPT_PIPELINED,
825		1'b0,
826		(OPT_EARLY_BRANCHING > 0)? 1'b1:1'b0,
827		OPT_PIPELINED_BUS_ACCESS,
828		OPT_CIS
829		};
830		// }}}
831	
832		always @(*)
833		begin
834			w_pcA_v = 0;
835			if ((!OPT_USERMODE)||(dcd_A[4] == dcd_gie))
836				w_pcA_v[(AW+1):0] = { dcd_pc[AW+1:2], 2'b00 };
837			else
838				w_pcA_v[(AW+1):0] = { upc[(AW+1):2], uhalt_phase, 1'b0 };
839		end
840	
841		// Op register addresses
842		// {{{
843		generate if (OPT_PIPELINED)
844		begin : OP_REG_ADVANEC
845			// {{{
846			reg	[4:0]	r_op_R;
847			reg	[4:0]	r_op_Aid, r_op_Bid;
848			reg		r_op_rA, r_op_rB;
849	
850			initial	r_op_R   = 0;
851			initial	r_op_Aid = 0;
852			initial	r_op_Bid = 0;
853			initial	r_op_rA  = 0;
854			initial	r_op_rB  = 0;
855			initial	op_Rcc = 0;
856			always @(posedge i_clk)
857			begin
858				if (op_ce && (!OPT_LOWPOWER || w_op_valid))
859				begin
860					r_op_R   <= dcd_R;
861					r_op_Aid <= dcd_A;
862					if ((dcd_rB)&&(!dcd_early_branch)&&(!dcd_illegal))
863						r_op_Bid <= dcd_B;
864					r_op_rA  <= (dcd_rA)&&(!dcd_early_branch)&&(!dcd_illegal);
865					r_op_rB  <= (dcd_rB)&&(!dcd_early_branch)&&(!dcd_illegal);
866					op_Rcc <= (dcd_Rcc)&&(dcd_wR)&&(dcd_R[4]==dcd_gie);
867				end
868	
869				if (op_lowpower_clear)
870				begin
871					r_op_rA <= 1'b0;
872					r_op_rB <= 1'b0;
873				end
874			end
875	
876			assign	op_R   = r_op_R;
877			assign	op_Aid = r_op_Aid;
878			assign	op_Bid = r_op_Bid;
879			assign	op_rA  = r_op_rA;
880			assign	op_rB  = r_op_rB;
881			// }}}
882		end else begin : OP_REG_COPY
883			// {{{
884			assign	op_R = dcd_R;
885			assign	op_Aid = dcd_A;
886			assign	op_Bid = dcd_B;
887			assign	op_rA  = dcd_rA;
888			assign	op_rB  = dcd_rB;
