890			always @(*)
891				op_Rcc = (dcd_Rcc)&&(dcd_wR)&&(dcd_R[4]==dcd_gie);
892			// }}}
893		end endgenerate
894		// }}}
895	
896		// r_op_Av -- The registered value of the op A register
897		// {{{
898		reg [2:0]	avsrc;
899		reg	[2:0]	bvsrc;
900		reg	[1:0]	bisrc;
901	
902		always @(*)
903		begin
904			avsrc = 3'b000;
905			if (!OPT_PIPELINED || op_ce)
906			begin
907				if (dcd_Apc)
908					avsrc = 3'b101;
909				else if (dcd_Acc)
910					avsrc = 3'b110;
911				else
912					avsrc = 3'b111;
913			end
914	
915			if (OPT_PIPELINED && wr_reg_ce)
916			begin
917				if (!op_ce && wr_reg_id == op_Aid && op_rA)
918					avsrc = 3'b100;
919				else if (op_ce && wr_reg_id == dcd_A)
920					avsrc = 3'b100;
921			end
922		end
923	
924	// 44313
925		initial	r_op_Av = 0;
926		always @(posedge i_clk)
927		begin
928			if (avsrc[2])
929			case(avsrc[1:0])
930			2'b00:	r_op_Av <= wr_gpreg_vl;
931			2'b01:	r_op_Av <= w_pcA_v;
932			2'b10:	r_op_Av <= { w_cpu_info, w_op_Av[22:16], (dcd_A[4])?w_uflags:w_iflags };
933			2'b11:	r_op_Av <= w_op_Av;
934			endcase
935	
936			if (op_lowpower_clear)
937				r_op_Av <= 0;
938		end
939		// }}}
940	
941		// w_op_B -- The registered value of the op B register
942		// {{{
943		always @(*)
944		begin
945			w_pcB_v = 0;
946			if ((!OPT_USERMODE)||(dcd_B[4] == dcd_gie))
947				w_pcB_v[(AW+1):0] = { dcd_pc[AW+1:2], 2'b00 };
948			else
949				w_pcB_v[(AW+1):0] = { upc[(AW+1):2], uhalt_phase, 1'b0 };
950		end
951	
952		always @(*)
953		if (!dcd_rB)
954			bisrc = 0;
955		else if ((OPT_PIPELINED)&&(wr_reg_ce)&&(wr_reg_id == dcd_B))
956			bisrc = 1;
957		else if (dcd_Bcc)
958			bisrc = 2;
959		else
960			bisrc = 3;
961	
962		always @(*)
963		case(bisrc[1:0])
964		2'b00: w_op_BnI = 0;
965		2'b01: w_op_BnI = wr_gpreg_vl;
966		2'b10: w_op_BnI = { w_cpu_info, w_op_Bv[22:16],
967					(dcd_B[4]) ? w_uflags : w_iflags };
968		2'b11: w_op_BnI = w_op_Bv;
969		endcase
970	
971		always @(*)
972		begin
973			bvsrc = 0;
974			if ((!OPT_PIPELINED)||(op_ce))
975			begin
976				if ((dcd_Bpc)&&(dcd_rB))
977					bvsrc = 3'b100;
978				else
979					bvsrc = 3'b101;
980			end else if ((OPT_PIPELINED)&&(op_rB)
981				&&(wr_reg_ce)&&(op_Bid == wr_reg_id))
982				bvsrc = 3'b110;
983		end
984	
985		initial	r_op_Bv = 0;
986		always @(posedge i_clk)
987		begin
988			if (bvsrc[2]) casez(bvsrc[1:0])
989			2'b00: r_op_Bv <= w_pcB_v + { dcd_I[29:0], 2'b00 };
990			2'b01: r_op_Bv <= w_op_BnI + dcd_I;
991			2'b1?: r_op_Bv <= wr_gpreg_vl;
992			endcase
993	
994			if (op_lowpower_clear)
995				r_op_Bv <= 0;
996		end
997		// }}}
998	
999		// op_F
1000		// {{{
1001		// The logic here has become more complex than it should be, no thanks
1002		// to Xilinx's Vivado trying to help.  The conditions are supposed to
1003		// be two sets of four bits: the top bits specify what bits matter, the
1004		// bottom specify what those top bits must equal.  However, two of
1005		// conditions check whether bits are on, and those are the only two
1006		// conditions checking those bits.  Therefore, Vivado complains that
1007		// these two bits are redundant.  Hence the convoluted expression
1008		// below, arriving at what we finally want in the (now wire net)
1009		// op_F.
1010		initial	r_op_F = 7'h00;
1011		always @(posedge i_clk)
1012		begin
1013			if ((!OPT_PIPELINED)||(op_ce))
1014				// Cannot do op_change_data_ce here since op_F depends
1015				// upon being either correct for a valid op, or correct
1016				// for the last valid op
1017			begin // Set the flag condition codes, bit order is [3:0]=VNCZ
1018				case(dcd_F[2:0])
1019				3'h0:	r_op_F <= 7'h00;	// Always
1020				3'h1:	r_op_F <= 7'h11;	// Z
1021				3'h2:	r_op_F <= 7'h44;	// LT
1022				3'h3:	r_op_F <= 7'h22;	// C
1023				3'h4:	r_op_F <= 7'h08;	// V
1024				3'h5:	r_op_F <= 7'h10;	// NE
1025				3'h6:	r_op_F <= 7'h40;	// GE (!N)
1026				3'h7:	r_op_F <= 7'h20;	// NC
1027				endcase
1028			end
1029	
1030			if (op_lowpower_clear)
1031				r_op_F <= 7'h00;
1032		end // Bit order is { (flags_not_used), VNCZ mask, VNCZ value }
