1396		generate if (OPT_PIPELINED)
1397		begin : GEN_DCDA_STALL
1398	
1399			assign	dcd_A_stall = (dcd_rA) // &&(dcd_valid) is checked for elsewhere
1400					&&((op_valid)||(i_mem_rdbusy)
1401						||(div_busy)||(fpu_busy))
1402					&&(((op_wF)||(cc_invalid_for_dcd))&&(dcd_Acc))
1403				||((dcd_rA)&&(dcd_Acc)&&(cc_invalid_for_dcd));
