1419		// dcd_B_stall, dcd_F_stall
1420		// {{{
1421		generate if (OPT_PIPELINED)
1422		begin : DCD_BF_STALLS
1423		// Stall if we have decoded an instruction that will read register B
1424		//	AND ... something that may write a (unknown) register is running
