1455					//
1456					((!dcd_zI)&&(
1457						((op_R == dcd_B)&&(op_wR))
1458						||((i_mem_rdbusy)&&(!dcd_pipe))
1459						||(((alu_busy ||
1460							div_busy || i_mem_rdbusy))
1461							&&(alu_reg == dcd_B))
1462						||((wr_reg_ce)&&(wr_reg_id[3:1] == 3'h7))
1463						))
