1821			// {{{
1822			initial	r_prelock_stall = 1'b0;
1823			always @(posedge i_clk)
1824			if (!OPT_PIPELINED || clear_pipeline)
1825				r_prelock_stall <= 1'b0;
1826			else if (op_valid && op_lock && r_bus_lock == 2'b00
1827							&& adf_ce_unconditional)
1828				r_prelock_stall <= 1'b1;
1829			else if (op_valid && dcd_valid
1830						&& (i_pf_valid || dcd_early_branch))
1831				r_prelock_stall <= 1'b0;
