1845			// r_bus_lock
1846			// {{{
1847			// Count 3 cycles.  The lock will only hold solid for three
1848			// cycles after the LOCK instruction is received.  Count those
1849			// cycles here.
1850			initial	r_bus_lock = 2'b00;
1851			always @(posedge i_clk)
1852			if (clear_pipeline)
1853				r_bus_lock <= 2'b00;
1854			else if (op_valid && (adf_ce_unconditional||mem_ce))
1855			begin
1856				if (r_bus_lock != 2'b00)
1857					r_bus_lock <= r_bus_lock - 1;
1858				else if (op_lock)
1859					r_bus_lock <= 2'b11;
1860			end
1861			// }}}
1862	
1863			assign	prelock_stall = OPT_PIPELINED && r_prelock_stall;
1864			assign	o_bus_lock    = |r_bus_lock;
1865			assign	o_mem_lock_pc = r_lock_pc;
1866			assign	last_lock_insn = (r_bus_lock <= 1);
