1873				always @(*)
1874				if (r_nojump_lock && (r_prelock_stall || r_bus_lock))
1875				begin
1876					assume(!dcd_early_branch);
1877					assume(!dcd_ljmp);
1878				end
1879	
1880				always @(*)
1881				if (!clear_pipeline) case(r_bus_lock)
1882				2'b11: if (!prelock_stall && r_nojump_lock)
1883					begin
1884					assert(op_valid && dcd_valid && i_pf_valid);
1885					end
1886				2'b10:	begin
1887					assert(!prelock_stall);
1888					if (r_nojump_lock)
1889					begin
1890						assert(dcd_valid);
1891						assert(op_valid + dcd_valid + i_pf_valid >= 2'b10);
1892					end end
1893				2'b01: begin
1894					assert(!prelock_stall);
1895					if (r_nojump_lock && !dcd_illegal)
1896					begin
1897						assert(op_valid || dcd_valid
1898								|| i_pf_valid);
1899					end end
1900				2'b00: assert(!prelock_stall);
1901				endcase
1902			end else begin
1903	
1904				always @(*)
1905					assert(!prelock_stall);
1906			end
1907			// }}}
1908	`endif
1909		end else begin : NO_BUSLOCK
1910			// {{{
1911			assign	prelock_stall = 1'b0;
1912			assign	o_bus_lock    = 1'b0;
1913			assign	o_mem_lock_pc = 0;
1914			assign	last_lock_insn= 1;
