2115	
2116						// if (op_sim_immv[19:4] == 16'h0031)
2117							// Exit(User reg), code cpu_wr_gpreg
2118							// Verilog offers no support for this.
2119							// Veri1ator might, but it isn't
2120							// standard.
2121						// if (op_sim_immv[19:4] == 16'h0030)
2122							// Exit(Normal reg), code cpu_wr_gpreg
2123							// $finish;
2124						// if (op_sim_immv[19:8] == 12'h001)
2125							// Exit(Immediate), code cpu_wr_gpreg
2126							// $finish;
2127						// }}}
2128					end
2129	
2130					if (op_sim_immv[19:0] == 20'h2ff)
2131					begin
2132						// DUMP all registers
2133						// {{{
2134						if (!op_gie)
2135						begin
2136						$write(" R0 : %08x ", regset[0]);
2137						$write(" R1 : %08x ", regset[1]);
2138						$write(" R2 : %08x ", regset[2]);
2139						$write(" R3 : %08x\n",regset[3]);
2140	
2141						$write(" R4 : %08x ", regset[4]);
2142						$write(" R5 : %08x ", regset[5]);
2143						$write(" R6 : %08x ", regset[6]);
2144						$write(" R7 : %08x\n",regset[7]);
2145	
2146						$write(" R8 : %08x ", regset[8]);
2147						$write(" R9 : %08x ", regset[9]);
2148						$write(" R10: %08x ", regset[10]);
2149						$write(" R11: %08x\n",regset[11]);
2150	
2151						$write(" R12: %08x ", regset[12]);
2152						$write(" SP : %08x ", regset[13]);
2153						$write(" CC : %08x ", w_iflags);
2154						$write(" PC : %08x\n", op_pc);
2155						end
2156	
2157						// }}}
2158					end
2159	
2160					if (op_sim_immv[19:5] == 15'h0010)
2161					begin
2162						// Dump a register
2163						// {{{
2164						$write("@%08x ", op_pc);
2165						$write(" R[%2d] = 0x", op_sim_immv[3:0]);
2166						// Dump a register
2167						if (wr_reg_ce&&wr_reg_id[3:0] == regid[3:0])
2168							$display("%08x", wr_gpreg_vl);
2169						else
2170							$display("%08x", regset[regid[3:0]]);
2171						// }}}
2172					end
2173					if (op_sim_immv[19:5] == 15'h0011)
2174					begin
2175						// SOUT(user register)
2176						// {{{
2177						if (wr_reg_ce && wr_reg_id[3:0] == op_sim_immv[3:0])
2178							$write("%c", wr_gpreg_vl[7:0]);
2179						else
2180							$write("%c", regset[op_sim_immv[3:0]][7:0]);
2181						// }}}
2182					end
2183	
2184					if (op_sim_immv[19:8] == 12'h004)
2185					begin
2186						// SOUT(Immediate)
2187						// {{{
2188						$write("%c", op_sim_immv[7:0]);
2189						// }}}
2190					end
2191	
2192					// ELSE unrecognized SIM instruction
2193	
2194					// Set alu_sim either way
2195					r_alu_sim <= 1'b1;
2196					// }}}
2197					end else
2198						r_alu_sim <= 1'b0;
2199	
2200					if (adf_ce_unconditional)
2201						r_alu_sim_immv <= op_sim_immv;
2202				end
2203	
2204				// Verilator lint_off UNUSED
2205				wire	unused_simmv;
2206				assign	unused_simmv = &{ 1'b0, regid[4] };
2207				// Verilator lint_on  UNUSED
2208				// }}}
2209			end
2210	
2211			assign	alu_sim      = r_alu_sim;
2212			assign	alu_sim_immv = r_alu_sim_immv;
2213	
2214		end else begin : NO_ALU_SIM
2215	
2216			assign	alu_sim = 0;
2217			assign	alu_sim_immv = 0;
2218			assign	cpu_sim = 0;
2219	
2220		end endgenerate
2221		// }}}
2222		// }}}
2223		////////////////////////////////////////////////////////////////////////
2224		//
2225		// PIPELINE STAGE #5 :: Write-back results
2226		// {{{
2227		////////////////////////////////////////////////////////////////////////
2228		//
2229		//
2230	
2231		//
2232		// This stage is not allowed to stall.  If results are ready to be
2233		// written back, they are written back at all cost.  Sleepy CPU's
2234		// won't prevent write back, nor debug modes, halting the CPU, nor
2235		// anything else.  Indeed, the (master_ce) bit is only as relevant
2236		// as knowinig something is available for writeback.
2237	
2238		// (was) wr_discard, wr_reg_ce
2239		// {{{
2240		//
2241		// Write back to our generic register set ...
2242		// When shall we write back?  On one of two conditions
2243		//	Note that the flags needed to be checked before issuing the
2244		//	bus instruction, so they don't need to be checked here.
2245		//	Further, alu_wR includes (set_cond), so we don't need to
2246		//	check for that here either.  It also includes alu_illegal, so
2247		//	again--doesn't need to be checked again here.
2248	
2249	/*
2250		// 12 inputs.  This implementation is made worse by wr_index.
2251		always @(*)
2252		case(wr_index)
2253		3'b000: wr_reg_ce  = dbgv;
2254		3'b001: wr_reg_ce  = i_mem_valid;
2255		//3'b010: wr_reg_ce = (!clear_pipeline)&&(alu_wR && alu_valid);
2256		3'b011: wr_reg_ce  = (!clear_pipeline)&&(div_valid)&&(!div_error);
2257		3'b1??: wr_reg_ce  = (!clear_pipeline)&&(fpu_valid)&&(!fpu_error);
2258		default: wr_reg_ce = (!clear_pipeline)&&(alu_wR && alu_valid);
2259		endcase
2260	*/
2261		// 7-LUT -- without FPU or wr_index (which wasn't needed)
2262		always @(*)
2263		begin
2264			wr_reg_ce = dbgv || i_mem_valid;
2265			if ((alu_wR && alu_valid)
2266					||(div_valid && !div_error)
2267					||(fpu_valid && !fpu_error))
2268				wr_reg_ce = wr_reg_ce || !clear_pipeline;
2269		end
2270	`ifdef	FORMAL
2271		always @(*)
2272		if (!i_reset && ((alu_wR && alu_valid)
2273					||(div_valid && !div_error)
2274					||(fpu_valid && !fpu_error)))
2275			assert(!dbgv && !i_mem_valid);
2276	
2277		always @(*)
2278		if (!i_reset)
2279		casez(wr_index)
2280		3'b000: assert(!i_mem_valid && (!alu_wR || !alu_valid)
2281				&& (!div_valid || div_error)
2282				&& (!fpu_valid || fpu_error));
2283		3'b001: assert(!dbgv && (!alu_wR || !alu_valid)
2284				&& (!div_valid || div_error)
2285				&& (!fpu_valid || fpu_error));
2286		3'b010: assert(!dbgv && !i_mem_valid
2287				// && (!alu_wR || !alu_valid)
2288				&& (!div_valid || div_error)
2289				&& (!fpu_valid || fpu_error));
2290		3'b011: assert(!dbgv && !i_mem_valid
2291				&& (!alu_wR || !alu_valid)
2292				// && (!div_valid || div_error)
2293				&& (!fpu_valid || fpu_error));
2294		3'b100: assert(!dbgv && !i_mem_valid
2295				&& (!alu_wR || !alu_valid)
2296				&& (!div_valid || div_error));
2297				// && (!fpu_valid || fpu_error);
2298		default: assert(0);
2299		endcase
2300	`endif
2301		// }}}
2302	
2303		// wr_reg_id, wr_write-cc, wr_write_scc, wr_write_ucc, wr_write_pc
2304		// {{{
2305		// Which register shall be written?
2306		//	COULD SIMPLIFY THIS: by adding three bits to these registers,
2307		//		One or PC, one for CC, and one for GIE match
2308		//	Note that the alu_reg is the register to write on a divide or
2309		//	FPU operation.
2310		generate if (OPT_USERMODE)
2311		begin : GEN_USERREG
2312			assign	wr_reg_id = (i_mem_valid) ? i_mem_wreg : alu_reg;
2313		end else begin : NO_USERREG
2314			assign	wr_reg_id[3:0] = (i_mem_valid)
2315						? i_mem_wreg[3:0] : alu_reg[3:0];
2316	
2317			assign	wr_reg_id[4] = 1'b0;
2318		end endgenerate
2319	
2320		// Are we writing to the CC register?
2321		// one 5-LUT ea
2322		assign	wr_write_cc = (wr_reg_id[3:0] == CPU_CC_REG);
2323		assign	wr_write_scc = (wr_reg_id[4:0] == {1'b0, CPU_CC_REG});
2324		assign	wr_write_ucc = (wr_reg_id[4:0] == {1'b1, CPU_CC_REG});
2325		// Are we writing to the PC?
2326		assign	wr_write_pc = (wr_reg_id[3:0] == CPU_PC_REG);
2327		// }}}
2328	
2329		// wr_?preg_vl: Select from among sources the value to be writtena
2330		// {{{
2331		// One 6-LUT per bit, or 32 6-LUTs w/o FPU
2332		always @(*)
2333		casez(wr_index)
2334		3'b000: wr_gpreg_vl = dbg_val;

